  const [terminalLogs, setTerminalLogs] = useState<{ text: string, type: 'sys' | 'warn' | 'crit' }[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Phishing State
  const [phishingTask, setPhishingTask] = useState<PhishingTask | null>(null);
  const [phishingFeedback, setPhishingFeedback] = useState<string | null>(null);
  const [score, setScore] = useState(0);

  if (!article) return <div>Статья не найдена</div>;

  const handleOsintScan = async () => {
    if (!nick) return alert("Введите никнейм!");
    setIsScanning(true);
    setTerminalLogs([{ text: "Инициализация OSINT-протокола SafeStep...", type: 'sys' }]);

    const findings = await simulateOsintScan(nick, "");

    for (let i = 0; i < findings.length; i++) {
        setTimeout(() => {
            setTerminalLogs(prev => [...prev, { text: findings[i], type: i % 2 === 0 ? 'sys' : 'warn' }]);
            if (i === findings.length - 1) {
                setTerminalLogs(prev => [...prev, { text: "🚨 КРИТИЧЕСКИЙ УРОВЕНЬ УГРОЗЫ: Данные скомпрометированы.", type: 'crit' }]);
                setIsScanning(false);
            }
        }, (i + 1) * 600);
    }
  };

  const loadPhishing = async () => {
    setPhishingFeedback(null);
    const task = await generatePhishingTask();
    setPhishingTask(task);
  };

  const checkPhishing = (userSaysPhishing: boolean) => {
    if (!phishingTask) return;
    if (userSaysPhishing === phishingTask.is_phishing) {
        setScore(s => s + 1);
        setPhishingFeedback(`✅ Верно! ${phishingTask.hint}`);
    } else {
        setScore(0);
        setPhishingFeedback(`❌ Ошибка! ${phishingTask.hint}`);
    }
  };

  useEffect(() => {
    if (activeTab === 'trainer' && article.type === 'phishing' && !phishingTask) {
        loadPhishing();
    }
  }, [activeTab]);

  if (zenMode) {
    return (
        <Layout>
            <div className="zen-container px-5">
                <div dangerouslySetInnerHTML={{ __html: BIG_ARTICLES_STORAGE[article.id] || "Контент в разработке..." }} />
                <div className="text-center mt-12">
                    <button onClick={() => setZenMode(false)} className="text-[#1e3c72] font-bold hover:underline">← Назад к инструментам</button>
                </div>
            </div>
        </Layout>
    );
  }

  return (
    <Layout>
      <main className="container-box article-view mt-32">
        <div className="article-header text-center mb-8">
            <span className="text-7xl mb-4 block">{article.emoji}</span>
            <h1 className="text-4xl font-bold text-[#1e3c72]">{article.title}</h1>
            <p className="text-gray-500 italic">{article.subtitle}</p>
        </div>

        <div className="tabs flex justify-center gap-2 mb-8 flex-wrap">
            <button className={`tab-btn ${activeTab === 'theory' ? 'active' : ''}`} onClick={() => setActiveTab('theory')}>📖 Теория</button>
            <button className={`tab-btn ${activeTab === 'practice' ? 'active' : ''}`} onClick={() => setActiveTab('practice')}>📜 Правила</button>
            <button className={`tab-btn ${activeTab === 'trainer' ? 'active' : ''}`} onClick={() => setActiveTab('trainer')}>⚙️ Инструмент</button>
        </div>

        {activeTab === 'theory' && (
            <div className="tab-content animate-in fade-in duration-500">
                <h3 className="text-2xl font-bold mb-4">Основные риски ❌</h3>
                <p className="text-gray-700 leading-relaxed">{article.description}</p>
                <div className="alert-box">
                    <b>Инсайд SafeStep:</b> Помни, что 90% данных для взлома человека хакеры берут не из вирусов, а из открытых источников.
                </div>
            </div>
        )}

        {activeTab === 'practice' && (
            <div className="tab-content animate-in fade-in duration-500">
                <h3 className="text-2xl font-bold mb-4">Золотые правила ✅</h3>
                <div className="space-y-4">
                    <div className="check-item flex items-center gap-3">
                        <input type="checkbox" id="p1" className="w-5 h-5" />
                        <label htmlFor="p1" className="cursor-pointer">Всегда проверяй настройки приватности.</label>
                    </div>
                    <div className="check-item flex items-center gap-3">
                        <input type="checkbox" id="p2" className="w-5 h-5" />
                        <label htmlFor="p2" className="cursor-pointer">Используй разные никнеймы для разных целей.</label>
                    </div>
                    <div className="check-item flex items-center gap-3">
                        <input type="checkbox" id="p3" className="w-5 h-5" />
                        <label htmlFor="p3" className="cursor-pointer">Не публикуй данные в реальном времени.</label>
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'trainer' && (
            <div className="tab-content animate-in fade-in duration-500">
                {article.type === 'past_revision' && (
                    <div className="space-y-6">
                        <div className="text-center">
                            <h3 className="text-xl font-bold">OSINT-Консоль 🛰️</h3>
                            <p className="text-sm text-gray-500">Симуляция глубокого сканирования личности.</p>
                        </div>
                        <div className="flex gap-2">
                            <input 
                                type="text" 
                                className="flex-grow p-3 border rounded-lg" 
                                placeholder="Введите никнейм (напр. super_ivan_2012)" 
                                value={nick}
                                onChange={e => setNick(e.target.value)}
                                disabled={isScanning}
                            />
                            <button 
                                onClick={handleOsintScan} 
                                className="bg-[#1e3c72] text-white px-6 py-3 rounded-lg font-bold disabled:opacity-50"
                                disabled={isScanning}
                            >
                                {isScanning ? 'ПОИСК...' : 'АУДИТ ⚡'}
                            </button>
                        </div>
                        <div id="terminal" className="min-h-[250px]">
                            {terminalLogs.length === 0 && <div className="text-gray-600 opacity-50">[SYSTEM] Ожидание ввода...</div>}
                            {terminalLogs.map((log, i) => (
                                <div key={i} className={`mb-2 ${log.type === 'crit' ? 'term-crit' : log.type === 'warn' ? 'term-warn' : 'term-sys'}`}>
                                    {`> [${new Date().toLocaleTimeString()}] ${log.text}`}
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {article.type === 'phishing' && (
                    <div className="space-y-6">
                        <div className="text-center">
                            <h3 className="text-xl font-bold">Тренажер "Крючок" 🎣</h3>
                            <p className="text-sm text-gray-500">Распознай фишинговое письмо. Счет: <b>{score}</b></p>
                        </div>
                        <div className="bg-white border-2 border-gray-200 rounded-xl p-6 shadow-sm">
                            {!phishingTask ? <div className="text-center py-10">Генерация задачи...</div> : (
                                <div className="space-y-4">
                                    <div className="border-b pb-4 flex items-center gap-4">
                                        <div className="w-10 h-10 bg-[#1e3c72] text-white rounded-full flex items-center justify-center font-bold">{phishingTask.sender[0]}</div>
                                        <div>
                                            <div className="font-bold">{phishingTask.sender}</div>
                                            <div className="text-xs text-gray-400">noreply@{phishingTask.url.split('/')[2] || 'service.com'}</div>
                                        </div>
                                    </div>
                                    <div className="text-gray-700 min-h-[80px]">{phishingTask.text}</div>
                                    <div className="bg-gray-100 p-2 rounded text-xs font-mono text-[#1e3c72]">{phishingTask.url}</div>

                                    {phishingFeedback ? (
                                        <div className={`p-4 rounded-lg font-bold ${phishingFeedback.startsWith('✅') ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                                            {phishingFeedback}
                                            <button onClick={loadPhishing} className="block w-full mt-4 bg-white border border-gray-300 py-2 rounded text-gray-800 hover:bg-gray-50">Следующее письмо ↻</button>
                                        </div>
                                    ) : (
                                        <div className="grid grid-cols-2 gap-4">
                                            <button onClick={() => checkPhishing(true)} className="bg-red-600 text-white py-3 rounded-lg font-bold hover:bg-red-700">ФИШИНГ! 🛑</button>
                                            <button onClick={() => checkPhishing(false)} className="bg-green-600 text-white py-3 rounded-lg font-bold hover:bg-green-700">БЕЗОПАСНО ✅</button>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {article.type === 'passwords' && (
                    <div className="space-y-6 text-center">
                        <h3 className="text-xl font-bold">Генератор "Сейф" 🛡️</h3>
