                                {nick || '••••••••••••'}
                            </div>
                            <button 
                                onClick={() => setNick(Math.random().toString(36).slice(-10) + "!" + Math.floor(Math.random()*100))}
                                className="read-more-btn"
                            >
                                Сгенерировать пароль 🔐
