        </div>
      </main>
    </Layout>
  );
};

export default ArticleDetail;

import React, { useState } from 'react';
import { QUIZ_DATA } from '../constants';
import { Layout } from './LayoutWrapper';

const Quiz: React.FC = () => {
  const [currentStep, setCurrentStep] = useState(0);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);
  const [feedback, setFeedback] = useState<{ isCorrect: boolean, text: string } | null>(null);

  const handleAnswer = (idx: number) => {
    const question = QUIZ_DATA[currentStep];
    const isCorrect = idx === question.correct;

    if (isCorrect) setScore(s => s + 1);
    setFeedback({ isCorrect, text: isCorrect ? question.desc : "Не совсем так. Попробуй вспомнить правила цифровой гигиены." });

    setTimeout(() => {
        setFeedback(null);
        if (currentStep < QUIZ_DATA.length - 1) {
            setCurrentStep(s => s + 1);
        } else {
            setFinished(true);
        }
    }, 2000);
  };

  return (
    <Layout>
      <header className="hero-gradient pt-20 pb-32 px-5 text-center">
        <h1 className="text-5xl font-black mb-4">Проверка знаний</h1>
        <p className="text-xl opacity-90">Узнай, насколько ты защищен в цифровом пространстве</p>
      </header>

      <main className="container-box mt-[-80px]">
        <div className="info-card">
            <h2 className="text-2xl font-bold text-[#1e3c72] mb-4">Интерактивный квест</h2>

            {finished ? (
                <div className="text-center py-10 animate-in zoom-in duration-500">
                    <div className="text-6xl mb-6">🏆</div>
                    <h3 className="text-3xl font-bold text-[#1e3c72] mb-2">Тест завершен!</h3>
                    <p className="text-xl text-gray-600 mb-8">Твой результат: <b>{score}</b> из <b>{QUIZ_DATA.length}</b></p>
                    <button onClick={() => window.location.reload()} className="read-more-btn max-w-xs mx-auto">Пройти еще раз</button>
                </div>
            ) : (
                <div className="question-block bg-[#fdfdfd] border border-gray-200 p-8 rounded-2xl">
                    <h3 className="text-gray-400 font-bold mb-2">Вопрос {currentStep + 1} из {QUIZ_DATA.length}</h3>
                    <p className="text-xl font-medium mb-8 text-[#1e3c72]">{QUIZ_DATA[currentStep].q}</p>

                    <div className="space-y-3">
                        {QUIZ_DATA[currentStep].options.map((opt, i) => (
                            <button 
                                key={i} 
                                onClick={() => !feedback && handleAnswer(i)}
                                className={`w-full p-4 text-left border-2 rounded-xl font-medium transition-all ${feedback ? 'cursor-not-allowed' : 'hover:border-[#1e3c72] hover:bg-blue-50'}`}
                                disabled={!!feedback}
                            >
                                {opt}
                            </button>
                        ))}
                    </div>

                    {feedback && (
                        <div className={`mt-6 p-4 rounded-xl font-bold animate-in slide-in-from-bottom duration-300 ${feedback.isCorrect ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                            {feedback.isCorrect ? '✅ ' : '❌ '}{feedback.text}
                        </div>
                    )}
                </div>
            )}
        </div>
      </main>
    </Layout>
  );
};

export default Quiz;

