import { simulateOsintScan, generatePhishingTask } from '../services/geminiService';
import { PhishingTask } from '../types';

const ArticleDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const article = ARTICLES.find(a => a.id === id);
  const [activeTab, setActiveTab] = useState('theory');
  const [zenMode, setZenMode] = useState(false);

  // Terminal State (OSINT)
  const [nick, setNick] = useState('');
  const [terminalLogs, setTerminalLogs] = useState<{ text: string, type: 'sys' | 'warn' | 'crit' }[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Phishing State
  const [phishingTask, setPhishingTask] = useState<PhishingTask | null>(null);
  const [phishingFeedback, setPhishingFeedback] = useState<string | null>(null);
  const [score, setScore] = useState(0);

  // Password Generation Word Lists
  const adjectives = ['Быстрый', 'Хитрый', 'Смелый', 'Яркий', 'Синий', 'Тихий', 'Верный', 'Умный', 'Грозный', 'Веселый', 'Золотой', 'Ночной'];
  const subjects = ['Кот', 'Пес', 'Лев', 'Робот', 'Дракон', 'Хакер', 'Сокол', 'Орел', 'Мастер', 'Волк', 'Ниндзя', 'Тигр'];
  const verbs = ['Видит', 'Знает', 'Любит', 'Хранит', 'Ищет', 'Помнит', 'Строит', 'Ценит', 'Ловит', 'Слышит', 'Пишет', 'Ждет'];
  const objects = ['Код', 'Мир', 'Сейф', 'Ключ', 'Свет', 'Путь', 'Знак', 'Сеть', 'Тайну', 'Факт', 'Степ', 'Плюс'];

  const generatePassphrase = () => {
    const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
    const sub = subjects[Math.floor(Math.random() * subjects.length)];
    const ver = verbs[Math.floor(Math.random() * verbs.length)];
    const obj = objects[Math.floor(Math.random() * objects.length)];
    const num = Math.floor(Math.random() * 900) + 100;
    const special = ['!', '?', '*', '#', '$'][Math.floor(Math.random() * 5)];
    return `${adj}_${sub}_${ver}_${obj}_${num}${special}`;
  };

