    setTerminalLogs([{ text: "Инициализация OSINT-протокола SafeStep...", type: 'sys' }]);

    const findings = await simulateOsintScan(nick, "");

    for (let i = 0; i < findings.length; i++) {
        setTimeout(() => {
            setTerminalLogs(prev => [...prev, { text: findings[i], type: i % 2 === 0 ? 'sys' : 'warn' }]);
            if (i === findings.length - 1) {
                setTerminalLogs(prev => [...prev, { text: "🚨 КРИТИЧЕСКИЙ УРОВЕНЬ УГРОЗЫ: Данные скомпрометированы.", type: 'crit' }]);
                setIsScanning(false);
            }
        }, (i + 1) * 600);
    }
