  const adjectives = ['Быстрый', 'Хитрый', 'Смелый', 'Яркий', 'Синий', 'Тихий', 'Верный', 'Умный', 'Грозный', 'Веселый', 'Золотой', 'Ночной'];
  const subjects = ['Кот', 'Пес', 'Лев', 'Робот', 'Дракон', 'Хакер', 'Сокол', 'Орел', 'Мастер', 'Волк', 'Ниндзя', 'Тигр'];
  const verbs = ['Видит', 'Знает', 'Любит', 'Хранит', 'Ищет', 'Помнит', 'Строит', 'Ценит', 'Ловит', 'Слышит', 'Пишет', 'Ждет'];
  const objects = ['Код', 'Мир', 'Сейф', 'Ключ', 'Свет', 'Путь', 'Знак', 'Сеть', 'Тайну', 'Факт', 'Степ', 'Плюс'];

