import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ARTICLES, BIG_ARTICLES_STORAGE } from '../constants';
import { Layout } from './LayoutWrapper';
import { simulateOsintScan, generatePhishingTask } from '../services/geminiService';
import { PhishingTask } from '../types';

interface GamingEvent {
  id: number;
  type: 'steam' | 'discord' | 'epic';
  title: string;
  desc: string;
  isScam: boolean;
  hint: string;
}

const ArticleDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const article = ARTICLES.find(a => a.id === id);
  const [activeTab, setActiveTab] = useState('theory');
  const [zenMode, setZenMode] = useState(false);

  // Terminal State (OSINT)
  const [nick, setNick] = useState('');
  const [terminalLogs, setTerminalLogs] = useState<{ text: string, type: 'sys' | 'warn' | 'crit' }[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Phishing State
  const [phishingTask, setPhishingTask] = useState<PhishingTask | null>(null);
  const [phishingFeedback, setPhishingFeedback] = useState<string | null>(null);
  const [score, setScore] = useState(0);

  // Incognito Leak Data State
  const [leakData, setLeakData] = useState<any>(null);

  // Gaming Mini-game State
  const [gameLevel, setGameLevel] = useState(0);
  const [gameFeedback, setGameFeedback] = useState<string | null>(null);
  const [gameScore, setGameScore] = useState(0);

  const gamingEvents: GamingEvent[] = [
    {
      id: 1,
      type: 'steam',
      title: 'Предложение обмена 🎁',
      desc: 'Пользователь [Admin_Support] предлагает обмен: вы отдаете ничего, вы получаете Knife | Doppler. Ссылка: steam-community.cc/trade/3921',
      isScam: true,
      hint: 'Ошибка в URL (steam-community.cc вместо steamcommunity.com) и подозрительная щедрость.'
    },
    {
      id: 2,
      type: 'discord',
      title: 'Discord Nitro Free! 🚀',
      desc: 'Ваш друг пишет: "Бро, тут реально раздают нитро, я уже забрал!". Ссылка: dlscord-nitro.com/gift',
      isScam: true,
      hint: 'Поддельный домен dlscord (через L вместо I) — классика фишинга.'
    },
    {
      id: 3,
      type: 'steam',
      title: 'Вход в аккаунт 🔐',
      desc: 'Пришло уведомление Steam Guard: попытка входа из города Шанхай (Китай). Это вы?',
      isScam: true,
      hint: 'Если вы не в Китае и не используете VPN — это попытка взлома. Жмите ОТКЛОНИТЬ.'
    },
    {
      id: 4,
      type: 'epic',
      title: 'Epic Games 2FA 🔑',
      desc: 'На вашу почту пришел код безопасности для входа, хотя вы сейчас не запускали лаунчер.',
      isScam: true,
      hint: 'Никому не говорите этот код. Кто-то узнал ваш пароль и пытается войти.'
    }
  ];

  // Password Generation Word Lists
  const adjectives = ['Быстрый', 'Хитрый', 'Смелый', 'Яркий', 'Синий', 'Тихий', 'Верный', 'Умный', 'Грозный', 'Веселый', 'Золотой', 'Ночной'];
  const subjects = ['Кот', 'Пес', 'Лев', 'Робот', 'Дракон', 'Хакер', 'Сокол', 'Орел', 'Мастер', 'Волк', 'Ниндзя', 'Тигр'];
  const verbs = ['Видит', 'Знает', 'Любит', 'Хранит', 'Ищет', 'Помнит', 'Строит', 'Ценит', 'Ловит', 'Слышит', 'Пишет', 'Ждет'];
  const objects = ['Код', 'Мир', 'Сейф', 'Ключ', 'Свет', 'Путь', 'Знак', 'Сеть', 'Тайну', 'Факт', 'Степ', 'Плюс'];

  const generatePassphrase = () => {
    const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
    const sub = subjects[Math.floor(Math.random() * subjects.length)];
    const ver = verbs[Math.floor(Math.random() * verbs.length)];
    const obj = objects[Math.floor(Math.random() * objects.length)];
    const num = Math.floor(Math.random() * 900) + 100;
    const special = ['!', '?', '*', '#', '$'][Math.floor(Math.random() * 5)];
    return `${adj}_${sub}_${ver}_${obj}_${num}${special}`;
  };

  const getGPUInfo = () => {
    try {
      const canvas = document.createElement('canvas');
      const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
      if (gl) {
        const debugInfo = (gl as WebGLRenderingContext).getExtension('WEBGL_debug_renderer_info');
        if (debugInfo) {
          return (gl as WebGLRenderingContext).getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);
        }
      }
    } catch (e) {
      return 'Не удалось определить';
    }
    return 'Не поддерживается';
  };

  const scanBrowserLeaks = () => {
    setLeakData({
      userAgent: navigator.userAgent,
      screen: `${window.screen.width}x${window.screen.height} (Color: ${window.screen.colorDepth}bit)`,
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      language: navigator.language,
      platform: (navigator as any).platform || 'Unknown',
      cookiesEnabled: navigator.cookieEnabled ? 'Да' : 'Нет',
      gpu: getGPUInfo()
    });
  };

  if (!article) return <div>Статья не найдена</div>;

  const handleOsintScan = async () => {
    if (!nick) return alert("Введите никнейм!");
    setIsScanning(true);
    setTerminalLogs([{ text: "Инициализация OSINT-протокола SafeStep...", type: 'sys' }]);

    const findings = await simulateOsintScan(nick, "");

    for (let i = 0; i < findings.length; i++) {
        setTimeout(() => {
            setTerminalLogs(prev => [...prev, { text: findings[i], type: i % 2 === 0 ? 'sys' : 'warn' }]);
            if (i === findings.length - 1) {
                setTerminalLogs(prev => [...prev, { text: "🚨 КРИТИЧЕСКИЙ УРОВЕНЬ УГРОЗЫ: Данные скомпрометированы.", type: 'crit' }]);
                setIsScanning(false);
            }
        }, (i + 1) * 600);
    }
  };

  const loadPhishing = async () => {
    setPhishingFeedback(null);
    const task = await generatePhishingTask();
    setPhishingTask(task);
  };

  const checkPhishing = (userSaysPhishing: boolean) => {
    if (!phishingTask) return;
    if (userSaysPhishing === phishingTask.is_phishing) {
        setScore(s => s + 1);
        setPhishingFeedback(`✅ Верно! ${phishingTask.hint}`);
    } else {
        setScore(0);
        setPhishingFeedback(`❌ Ошибка! ${phishingTask.hint}`);
    }
  };

  const handleGameDecision = (isAccept: boolean) => {
    const event = gamingEvents[gameLevel];
    // In our simulator, all events are dangerous, so 'Accept' is always wrong
    const isCorrect = isAccept === false; 

    if (isCorrect) {
      setGameScore(s => s + 1);
      setGameFeedback(`✅ Правильно! Вы отклонили угрозу. ${event.hint}`);
    } else {
      setGameFeedback(`❌ Ой! Аккаунт взломан. ${event.hint}`);
    }

    setTimeout(() => {
      setGameFeedback(null);
      if (gameLevel < gamingEvents.length - 1) {
        setGameLevel(l => l + 1);
      } else {
        // End game or reset
      }
    }, 3000);
  };

  useEffect(() => {
    if (activeTab === 'trainer' && article.type === 'phishing' && !phishingTask) {
        loadPhishing();
    }
    if (activeTab === 'trainer' && article.type === 'incognito') {
        scanBrowserLeaks();
    }
  }, [activeTab]);

  if (zenMode) {
    return (
        <Layout>
            <div className="zen-container px-5">
                <div dangerouslySetInnerHTML={{ __html: BIG_ARTICLES_STORAGE[article.id] || "Контент в разработке..." }} />
                <div className="text-center mt-12 pb-20">
                    <button onClick={() => setZenMode(false)} className="text-[#1e3c72] font-bold hover:underline flex items-center justify-center gap-2 mx-auto">
                        <span>←</span> Назад к инструментам
                    </button>
                </div>
            </div>
        </Layout>
    );
  }

  return (
    <Layout>
      <main className="container-box article-view mt-32">
        <div className="article-header text-center mb-8">
            <span className="text-7xl mb-4 block">{article.emoji}</span>
            <h1 className="text-4xl font-bold text-[#1e3c72]">{article.title}</h1>
            <p className="text-gray-500 italic">{article.subtitle}</p>
        </div>

        <div className="tabs flex justify-center gap-2 mb-8 flex-wrap">
            <button className={`tab-btn ${activeTab === 'theory' ? 'active' : ''}`} onClick={() => setActiveTab('theory')}>📖 Теория</button>
            <button className={`tab-btn ${activeTab === 'practice' ? 'active' : ''}`} onClick={() => setActiveTab('practice')}>📜 Правила</button>
            <button className={`tab-btn ${activeTab === 'trainer' ? 'active' : ''}`} onClick={() => setActiveTab('trainer')}>⚙️ Инструмент</button>
        </div>

        {activeTab === 'theory' && (
            <div className="tab-content animate-in fade-in duration-500">
                <h3 className="text-2xl font-bold mb-4 text-[#1e3c72]">Основные риски ❌</h3>
                <p className="text-gray-700 leading-relaxed">{article.description}</p>
                <div className="alert-box">
                    <b>Инсайд SafeStep:</b> Помни, что 90% данных для взлома человека хакеры берут не из вирусов, а из открытых источников.
                </div>
            </div>
        )}

        {activeTab === 'practice' && (
            <div className="tab-content animate-in fade-in duration-500">
                <h3 className="text-2xl font-bold mb-4 text-[#1e3c72]">Золотые правила ✅</h3>
                <div className="space-y-4">
                    <div className="check-item flex items-center gap-3">
                        <input type="checkbox" id="p1" className="w-5 h-5 accent-[#1e3c72]" />
                        <label htmlFor="p1" className="cursor-pointer">Всегда проверяй настройки приватности.</label>
                    </div>
                    <div className="check-item flex items-center gap-3">
                        <input type="checkbox" id="p2" className="w-5 h-5 accent-[#1e3c72]" />
                        <label htmlFor="p2" className="cursor-pointer">Используй разные никнеймы для разных целей.</label>
                    </div>
                    <div className="check-item flex items-center gap-3">
                        <input type="checkbox" id="p3" className="w-5 h-5 accent-[#1e3c72]" />
                        <label htmlFor="p3" className="cursor-pointer">Не публикуй данные в реальном времени.</label>
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'trainer' && (
            <div className="tab-content animate-in fade-in duration-500">
                {article.type === 'past_revision' && (
                    <div className="space-y-6">
                        <div className="text-center">
                            <h3 className="text-xl font-bold text-[#1e3c72]">OSINT-Консоль 🛰️</h3>
                            <p className="text-sm text-gray-500">Симуляция глубокого сканирования личности.</p>
                        </div>
                        <div className="flex flex-col sm:flex-row gap-3">
                            <input 
                                type="text" 
                                className="flex-grow p-4 border-2 border-gray-200 bg-white text-gray-800 rounded-xl focus:border-[#1e3c72] outline-none transition-colors" 
                                placeholder="Введите никнейм" 
                                value={nick}
                                onChange={e => setNick(e.target.value)}
                                disabled={isScanning}
                            />
                            <button onClick={handleOsintScan} disabled={isScanning} className="bg-[#1e3c72] text-white px-8 py-4 rounded-xl font-bold">АУДИТ ⚡</button>
                        </div>
                        <div id="terminal" className="min-h-[250px]">
                            {terminalLogs.map((log, i) => (
                                <div key={i} className={`mb-2 ${log.type === 'crit' ? 'term-crit' : log.type === 'warn' ? 'term-warn' : 'term-sys'}`}>
                                    {`> ${log.text}`}
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {article.type === 'gaming' && (
                    <div className="space-y-6">
                        <div className="text-center">
                            <h3 className="text-xl font-bold text-[#1e3c72]">Account Defender 🎮</h3>
