                                    <button onClick={() => {setGameLevel(0); setGameScore(0);}} className="mt-6 bg-[#1e3c72] text-white px-6 py-2 rounded-lg">Заново ↻</button>
                                </div>
                            ) : (
                                <div className="space-y-6">
                                    <div className="flex justify-between items-center text-xs text-gray-500 uppercase tracking-widest border-b border-gray-800 pb-2">
                                        <span>System Alert</span>
                                        <span>12:45 PM</span>
                                    </div>
                                    <div className="bg-[#222] p-4 rounded-xl border border-gray-700 animate-in slide-in-from-top duration-300">
                                        <div className="flex items-center gap-3 mb-2">
                                            <div className={`w-3 h-3 rounded-full ${gamingEvents[gameLevel].type === 'steam' ? 'bg-blue-500' : 'bg-purple-500'}`}></div>
                                            <span className="text-white font-bold text-sm uppercase">{gamingEvents[gameLevel].type}</span>
                                        </div>
                                        <h4 className="text-white font-bold mb-1">{gamingEvents[gameLevel].title}</h4>
