  const [phishingTask, setPhishingTask] = useState<PhishingTask | null>(null);
  const [phishingFeedback, setPhishingFeedback] = useState<string | null>(null);
  const [score, setScore] = useState(0);

  // Incognito Leak Data State
  const [leakData, setLeakData] = useState<any>(null);

  // Gaming Arcade Game State
  const [gameStatus, setGameStatus] = useState<'idle' | 'playing' | 'gameover'>('idle');
  const [gameScore, setGameScore] = useState(0);
  const [gameLives, setGameLives] = useState(3);
  const [objects, setObjects] = useState<GameObject[]>([]);
  const [shieldPos, setShieldPos] = useState(50); // percentage 0-100
  const gameContainerRef = useRef<HTMLDivElement>(null);
  const gameLoopRef = useRef<number | null>(null);

  const spawnObject = () => {
    const isGood = Math.random() > 0.4;
    const items = isGood 
      ? [{ icon: '🛡️', name: '2FA' }, { icon: '🔑', name: 'Password' }, { icon: '📱', name: 'App' }]
      : [{ icon: '🎣', name: 'Phish' }, { icon: '💀', name: 'Virus' }, { icon: '🤖', name: 'Bot' }];
    const item = items[Math.floor(Math.random() * items.length)];

    return {
      id: Date.now() + Math.random(),
      x: Math.random() * 90,
      y: -10,
      type: isGood ? 'good' : 'bad' as 'good' | 'bad',
      icon: item.icon,
      name: item.name
    };
  };

  const startGame = () => {
    setGameStatus('playing');
    setGameScore(0);
    setGameLives(3);
    setObjects([]);
  };

  useEffect(() => {
    if (gameStatus !== 'playing') return;

    const moveObjects = () => {
      setObjects(prev => {
        const next = prev.map(obj => ({ ...obj, y: obj.y + 1.5 }));

        // Filter out items that fell out of view
        const visible = next.filter(obj => {
          if (obj.y > 100) {
            if (obj.type === 'good') setGameLives(l => l - 1); // Losing a good item hurts
            return false;
          }

          // Collision Check
          const isColliding = obj.y > 80 && obj.y < 95 && Math.abs(obj.x - shieldPos) < 15;
          if (isColliding) {
            if (obj.type === 'good') {
              setGameScore(s => s + 10);
            } else {
              setGameLives(l => l - 1);
            }
            return false;
          }
          return true;
        });

        // Spawn new ones
        if (visible.length < 5 && Math.random() > 0.97) {
          visible.push(spawnObject());
        }

        return visible;
      });

      if (gameLives <= 0) {
        setGameStatus('gameover');
      } else {
        gameLoopRef.current = requestAnimationFrame(moveObjects);
      }
    };

    gameLoopRef.current = requestAnimationFrame(moveObjects);
    return () => {
      if (gameLoopRef.current) cancelAnimationFrame(gameLoopRef.current);
    };
  }, [gameStatus, shieldPos, gameLives]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (gameContainerRef.current) {
      const rect = gameContainerRef.current.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 100;
      setShieldPos(Math.min(Math.max(x, 5), 95));
    }
  };

  // Logic for other articles...
  const scanBrowserLeaks = () => {
    setLeakData({
      userAgent: navigator.userAgent,
      screen: `${window.screen.width}x${window.screen.height}`,
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      language: navigator.language,
      gpu: (function() {
        const c = document.createElement('canvas');
        const gl = c.getContext('webgl');
        if (!gl) return 'Unknown';
        const d = gl.getExtension('WEBGL_debug_renderer_info');
        return d ? gl.getParameter(d.UNMASKED_RENDERER_WEBGL) : 'Generic GPU';
      })()
    });
  };

  const generatePassphrase = () => {
    const adjectives = ['Быстрый', 'Хитрый', 'Смелый', 'Яркий', 'Синий', 'Тихий'];
    const subjects = ['Кот', 'Пес', 'Лев', 'Робот', 'Дракон', 'Хакер'];
    const verbs = ['Видит', 'Знает', 'Любит', 'Хранит', 'Ищет'];
    const objects = ['Код', 'Мир', 'Сейф', 'Ключ', 'Свет', 'Путь'];
    const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
    const sub = subjects[Math.floor(Math.random() * subjects.length)];
    const ver = verbs[Math.floor(Math.random() * verbs.length)];
    const obj = objects[Math.floor(Math.random() * objects.length)];
    return `${adj}_${sub}_${ver}_${obj}_${Math.floor(Math.random()*900)+100}!`;
  };

  if (!article) return <div>Статья не найдена</div>;

  const handleOsintScan = async () => {
    if (!nick) return alert("Введите никнейм!");
    setIsScanning(true);
    setTerminalLogs([{ text: "Инициализация...", type: 'sys' }]);
    const findings = await simulateOsintScan(nick, "");
    setTerminalLogs(findings.map((f: string) => ({ text: f, type: 'warn' })));
    setIsScanning(false);
  };

  if (zenMode) {
    return (
        <Layout>
            <div className="zen-container px-5">
                <div dangerouslySetInnerHTML={{ __html: BIG_ARTICLES_STORAGE[article.id] || "Контент в разработке..." }} />
                <div className="text-center mt-12 pb-20">
                    <button onClick={() => setZenMode(false)} className="text-[#1e3c72] font-bold hover:underline">← Назад</button>
                </div>
            </div>
        </Layout>
    );
  }

  return (
    <Layout>
      <main className="container-box article-view mt-32">
        <div className="article-header text-center mb-8">
            <span className="text-7xl mb-4 block">{article.emoji}</span>
            <h1 className="text-4xl font-bold text-[#1e3c72]">{article.title}</h1>
            <p className="text-gray-500 italic">{article.subtitle}</p>
        </div>

        <div className="tabs flex justify-center gap-2 mb-8 flex-wrap">
            <button className={`tab-btn ${activeTab === 'theory' ? 'active' : ''}`} onClick={() => setActiveTab('theory')}>📖 Теория</button>
            <button className={`tab-btn ${activeTab === 'practice' ? 'active' : ''}`} onClick={() => setActiveTab('practice')}>📜 Правила</button>
            <button className={`tab-btn ${activeTab === 'trainer' ? 'active' : ''}`} onClick={() => setActiveTab('trainer')}>⚙️ Инструмент</button>
        </div>

        {activeTab === 'theory' && (
            <div className="tab-content">
                <h3 className="text-2xl font-bold mb-4 text-[#1e3c72]">Основные риски ❌</h3>
                <p className="text-gray-700 leading-relaxed mb-6">{article.description}</p>
                <div className="alert-box">
                    <b>SafeStep Tip:</b> Игры — это не только веселье, но и ответственность за свои данные.
                </div>
            </div>
        )}

        {activeTab === 'practice' && (
            <div className="tab-content">
                <h3 className="text-2xl font-bold mb-4 text-[#1e3c72]">Золотые правила ✅</h3>
                <ul className="space-y-4">
                  <li className="flex items-center gap-3">✅ Включи 2FA везде.</li>
                  <li className="flex items-center gap-3">✅ Не переходи по ссылкам на "халяву".</li>
                  <li className="flex items-center gap-3">✅ Проверяй домены сайтов авторизации.</li>
                </ul>
            </div>
        )}

        {activeTab === 'trainer' && (
            <div className="tab-content">
                {article.type === 'gaming' && (
                  <div className="space-y-6">
                    <div className="text-center">
                      <h3 className="text-xl font-bold text-[#1e3c72]">Defend Your Inventory 🛡️</h3>
                      <p className="text-sm text-gray-500 mb-4">Лови защиту, уклоняйся от угроз! Счет: <b>{gameScore}</b> | Жизни: <b>{'❤️'.repeat(gameLives)}</b></p>
                    </div>

                    <div 
                      ref={gameContainerRef}
                      onMouseMove={handleMouseMove}
                      className="relative w-full h-[400px] bg-[#0a0a0a] rounded-3xl overflow-hidden cursor-none border-4 border-[#1e3c72] shadow-2xl"
                    >
                      {gameStatus === 'idle' && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 z-20">
                          <h4 className="text-white text-2xl font-bold mb-4">Cyber Shield Arcade</h4>
                          <p className="text-gray-300 text-sm mb-6 px-10 text-center">Лови 2FA и Ключи. Не трогай Черепа и Крючки!</p>
                          <button onClick={startGame} className="bg-blue-600 text-white px-10 py-3 rounded-full font-bold hover:bg-blue-500">СТАРТ 🚀</button>
                        </div>
                      )}

                      {gameStatus === 'gameover' && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 z-20">
                          <h4 className="text-red-500 text-3xl font-bold mb-2">АККАУНТ ВЗЛОМАН!</h4>
                          <p className="text-white mb-6">Ваш счет: {gameScore}</p>
                          <button onClick={startGame} className="bg-white text-black px-8 py-2 rounded-full font-bold">ПОПРОБОВАТЬ СНОВА ↻</button>
                        </div>
                      )}

                      {/* Falling Objects */}
                      {objects.map(obj => (
                        <div 
                          key={obj.id} 
                          className="absolute text-3xl transition-transform duration-75 select-none"
                          style={{ left: `${obj.x}%`, top: `${obj.y}%` }}
                        >
                          {obj.icon}
                        </div>
                      ))}

                      {/* Shield / Player */}
                      <div 
                        className="absolute bottom-4 h-3 w-16 bg-blue-400 rounded-full shadow-[0_0_15px_rgba(96,165,250,0.8)]"
                        style={{ left: `${shieldPos}%`, transform: 'translateX(-50%)' }}
                      >
                        <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-2xl">🛡️</div>
                      </div>
                    </div>
                  </div>
                )}

                {/* Integration with other tools (simplified for brevity) */}
                {article.id === 'incognito' && (
                  <div className="space-y-4">
                    <h3 className="text-xl font-bold text-center">Privacy Leak Scan</h3>
