                  </div>
                )}

                {article.id === 'passwords' && (
                   <div className="text-center">
                     <button onClick={() => setNick(generatePassphrase())} className="read-more-btn">Generate Passphrase</button>
                     <div className="mt-4 text-2xl font-mono">{nick}</div>
                   </div>
                )}

                {/* Long-read Link */}
                <div className="mt-12 p-8 bg-[#f8faff] rounded-3xl border border-[#e1e8f5] text-center">
                    <h4 className="text-xl font-bold text-[#1e3c72] mb-3">Глубокое погружение</h4>
                    <p className="text-gray-600 mb-6">Мы подготовили подробный материал, раскрывающий все секреты этой темы на примерах.</p>
                    <button onClick={() => setZenMode(true)} className="bg-[#1e3c72] text-white px-10 py-4 rounded-2xl font-bold hover:scale-105 transition-transform">Читать полную статью</button>
