const adjectives = [
  'Быстрый', 'Хитрый', 'Смелый', 'Яркий', 'Синий', 'Тихий', 'Верный', 'Умный', 'Грозный', 'Веселый', 
  'Золотой', 'Ночной', 'Ловкий', 'Мощный', 'Тайный', 'Дикий', 'Великий', 'Мудрый', 'Рыжий', 'Черный',
  'Лесной', 'Горный', 'Звездный', 'Вечный', 'Острый', 'Стальной', 'Белый', 'Красный', 'Зеленый', 'Громкий'
];

const subjects = [
  'Кот', 'Пес', 'Лев', 'Робот', 'Дракон', 'Хакер', 'Сокол', 'Орел', 'Мастер', 'Волк', 
  'Ниндзя', 'Тигр', 'Медведь', 'Маг', 'Рыцарь', 'Снайпер', 'Пилот', 'Герой', 'Агент', 'Викинг',
  'Призрак', 'Странник', 'Доктор', 'Профи', 'Охотник', 'Демон', 'Ангел', 'Гном', 'Эльф', 'Пират'
];

const verbs = [
  'Видит', 'Знает', 'Любит', 'Хранит', 'Ищет', 'Помнит', 'Строит', 'Ценит', 'Ловит', 'Слышит', 
  'Пишет', 'Ждет', 'Спит', 'Бежит', 'Летит', 'Думает', 'Кушает', 'Ходит', 'Плывет', 'Играет',
  'Создает', 'Скрывает', 'Бережет', 'Проверяет', 'Защищает', 'Меняет', 'Сломает', 'Держит', 'Верит', 'Мечтает'
];

const objects = [
  'Код', 'Мир', 'Сейф', 'Ключ', 'Свет', 'Путь', 'Знак', 'Сеть', 'Тайну', 'Факт', 
  'Степ', 'Плюс', 'Гайд', 'Данные', 'Файл', 'Сервер', 'Стек', 'Бит', 'Байт', 'Лог',
  'Скилл', 'Профиль', 'Аккаунт', 'Токен', 'Шифр', 'Кеш', 'Хост', 'Порт', 'Линк', 'Диск'
];

const years = ['2023', '2024', '2025', '2026', '777', '1337', '99', '01'];
const specials = ['!', '?', '*', '#', '$', '@', '&', '%'];

export function generateSecurePassphrase(): string {
  const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
  const sub = subjects[Math.floor(Math.random() * subjects.length)];
  const ver = verbs[Math.floor(Math.random() * verbs.length)];
  const obj = objects[Math.floor(Math.random() * objects.length)];
  const year = years[Math.floor(Math.random() * years.length)];
  const spec = specials[Math.floor(Math.random() * specials.length)];

  // Format: Adjective_Subject_Verb_Object_Year+Special
  return `${adj}_${sub}_${ver}_${obj}_${year}${spec}`;
}

