                  <p className="text-gray-500 mb-2">Распознай фишинг в личных сообщениях. Счет: <b>{gameScore}</b></p>
                </div>

                {!currentMessage ? (
                  <div className="bg-gray-100 p-12 rounded-[40px] text-center border-4 border-dashed border-[#1e3c72]/20">
                    <button onClick={spawnGameMessage} className="read-more-btn max-w-xs mx-auto text-xl">Начать симуляцию 🚀</button>
                  </div>
                ) : (
                  <div className="bg-[#1a1c23] p-8 rounded-[40px] shadow-2xl relative overflow-hidden">
                    <div className="flex items-start gap-4 mb-6">
                      <div className="w-12 h-12 bg-blue-500/20 text-2xl flex items-center justify-center rounded-2xl shrink-0">
                        {currentMessage.avatar}
                      </div>
                      <div className="flex-grow">
                        <div className="text-white font-bold text-sm mb-1">{currentMessage.sender} <span className="text-[10px] text-blue-400 opacity-60 ml-2">СЕГОДНЯ</span></div>
                        <div className="bg-[#2a2e38] text-gray-200 p-4 rounded-2xl rounded-tl-none border border-gray-700 shadow-inner">
                          {currentMessage.text}
                        </div>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mt-8">
                      <button 
                        onClick={() => handleGameChoice(false)}
                        className="py-4 rounded-2xl bg-green-600/20 text-green-400 border-2 border-green-600/50 font-black hover:bg-green-600 hover:text-white transition-all"
                        disabled={!!gameFeedback}
                      >
                        ВСЁ ЧИСТО ✅
                      </button>
                      <button 
                        onClick={() => handleGameChoice(true)}
                        className="py-4 rounded-2xl bg-red-600/20 text-red-400 border-2 border-red-600/50 font-black hover:bg-red-600 hover:text-white transition-all"
                        disabled={!!gameFeedback}
                      >
                        ЭТО СКAM! 🏴‍☠️
                      </button>
                    </div>

                    {gameFeedback && (
                      <div className={`mt-6 p-6 rounded-3xl animate-in slide-in-from-bottom duration-300 border-2 ${gameFeedback.isCorrect ? 'bg-green-600/10 border-green-600 text-green-400' : 'bg-red-600/10 border-red-600 text-red-400'}`}>
                        <div className="font-black mb-1">{gameFeedback.isCorrect ? 'ВЕРНО! 🎯' : 'ОШИБКА! 💥'}</div>
                        <div className="text-sm opacity-90">{gameFeedback.text}</div>
                        <div className="mt-4 text-center text-xs opacity-50 font-bold uppercase tracking-widest">Следующее сообщение...</div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {article.type === 'incognito' && <IncognitoTool />}
            {article.type === 'smartphone_spy' && <SmartphoneSpyTool />}
            {article.type === 'phishing' && <PhishingTrainer />}
            {article.type === 'aiandyourphotos' && <AITool />}

            {article.type === 'past_revision' && (
              <div className="space-y-6">
                <div className="p-3 rounded-2xl bg-[#e1e8f5] shadow-inner border-2 border-[#1e3c72]/10">
                  <input 
                    className="w-full p-5 bg-white text-[#1e3c72] border-2 border-[#1e3c72]/20 rounded-xl font-black text-xl placeholder-[#1e3c72]/40 focus:border-[#1e3c72] outline-none transition-all shadow-sm" 
                    placeholder="Введи ник для симуляции (напр. IWOSS)" 
                    value={nick} 
                    onChange={e => setNick(e.target.value)}
                  />
                </div>
                <button onClick={handleOsintScan} disabled={isScanning} className="read-more-btn py-5 text-xl">
                  {isScanning ? 'ИДЕТ ПОИСК...' : 'Аудит личности 🕵️'}
                </button>
                <div id="terminal" className="mt-6 border-4 border-[#1e3c72]/30">
                  {terminalLogs.length === 0 && <div className="opacity-40 italic">Ожидание инициализации протокола...</div>}
                  {terminalLogs.map((l, i) => (
                    <div key={i} className={`mb-2 font-mono ${l.type === 'sys' ? 'text-green-400' : 'text-yellow-400'}`}>
                      <span className="opacity-50 mr-2">></span>{l.text}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {article.type === 'passwords' && (
              <div className="space-y-8 text-center">
                <h3 className="text-2xl font-black text-[#1e3c72]">Генератор "Сейф" 🔐</h3>
                <div className="bg-white border-4 border-[#e1e8f5] rounded-[40px] p-12 shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></div>
                  <div className="text-xl md:text-3xl font-mono font-black tracking-tight text-[#1e3c72] mb-10 select-all break-words bg-gray-50 p-8 rounded-3xl border-2 border-dashed border-[#1e3c72]/20">
                    {nick || '••••_••••_••••_••••'}
                  </div>
                  <button onClick={() => setNick(generateSecurePassphrase())} className="read-more-btn py-6 text-2xl shadow-xl">Сгенерировать ⚡</button>
                </div>
              </div>
            )}

            {article.type === 'geolocation' && (
              <div className="space-y-8">
                <div className="text-center">
                  <h3 className="text-2xl font-black text-[#1e3c72]">Ловушка местоположения 📍</h3>
                  <p className="text-gray-500">Посмотри, как мошенники маскируют запрос на геолокацию под "призы".</p>
                </div>

                <div className="bg-gray-100 p-8 rounded-[30px] border-4 border-dashed border-gray-300 max-w-md mx-auto relative overflow-hidden min-h-[300px] flex flex-col justify-center">
                  {geoStep === 'invite' && (
                    <div className="text-center space-y-6 animate-in fade-in">
                      <div className="text-5xl">🎁</div>
                      <h4 className="text-xl font-bold">Вы выиграли iPhone 15 Pro!</h4>
                      <p className="text-gray-600 text-sm">Чтобы мы могли рассчитать время бесплатной доставки до вас, нажмите кнопку ниже.</p>
                      <button 
                        onClick={() => {
                          setIsFakeLoading(true);
                          setTimeout(() => { setIsFakeLoading(false); setGeoStep('request'); }, 1500);
                        }} 
                        className="bg-[#1e3c72] text-white px-8 py-4 rounded-2xl font-bold w-full hover:scale-105 transition-transform"
                      >
                        {isFakeLoading ? 'ПРОВЕРКА АКЦИИ...' : 'РАССЧИТАТЬ ДОСТАВКУ'}
                      </button>
                    </div>
                  )}

                  {geoStep === 'request' && (
                    <div className="bg-white p-6 rounded-2xl shadow-2xl animate-in zoom-in duration-300 border border-gray-200">
                      <div className="flex items-center gap-4 mb-4">
                        <div className="bg-blue-100 p-2 rounded-lg text-lg">📍</div>
                        <div>
                          <h4 className="font-bold text-sm">Разрешить доступ?</h4>
                          <p className="text-[10px] text-gray-500">Сайт <b>gift-winner.io</b> хочет знать ваше точное местоположение.</p>
                        </div>
                      </div>
                      <div className="grid grid-cols-2 gap-2">
                        <button onClick={() => setGeoStep('result')} className="bg-blue-600 text-white py-2 rounded-lg text-xs font-bold">РАЗРЕШИТЬ</button>
                        <button onClick={() => setGeoStep('invite')} className="bg-gray-100 text-gray-600 py-2 rounded-lg text-xs font-bold">БЛОКИРОВАТЬ</button>
                      </div>
                      <div className="mt-4 p-3 bg-red-50 text-red-700 text-[10px] rounded-lg border border-red-100 font-bold">
                        АНАЛИЗ SAFESTEP: Мошенник маскирует запрос под "логистику". Это обман для получения вашего адреса.
                      </div>
                    </div>
                  )}

                  {geoStep === 'result' && (
                    <div className="text-center space-y-4 animate-in fade-in">
                      <div className="text-4xl">😱</div>
                      <h4 className="text-red-600 font-black text-xl">ДАННЫЕ ПЕРЕДАНЫ!</h4>
                      <p className="text-xs text-gray-600">Злоумышленник получил ваши координаты. iPhone — фейк, угроза — реальна.</p>
                      <button onClick={() => setGeoStep('invite')} className="text-blue-600 font-bold text-sm hover:underline">Попробовать еще раз</button>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        )}

        <div className="mt-12 text-center border-t pt-8">
          <Link to="/articles" className="text-gray-400 hover:text-[#1e3c72] font-black transition-colors uppercase tracking-widest text-sm">
            ← Назад к списку тем
          </Link>
        </div>
      </main>
    </Layout>
  );
};

