import React, { useState, useEffect } from 'react';

interface AIReport {
  labels: { key: string; val: string; conf: string }[];
  riskLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  riskTitle: string;
  riskDesc: string;
}

export const AITool: React.FC = () => {
  const [selectedPhoto, setSelectedPhoto] = useState<number | null>(null);
  const [status, setStatus] = useState<'IDLE' | 'SCANNING' | 'DONE'>('IDLE');
  const [scanProgress, setScanProgress] = useState(0);

  const photos = [
    {
      id: 1,
      url: "https://images.unsplash.com/photo-1517841905240-472988babdf9?w=400&h=400&fit=crop",
      title: "Селфи",
      report: {
        labels: [
          { key: "Лицо", val: "Биометрический профиль создан", conf: "99.8%" },
          { key: "Бренд", val: "Nike (Target: High Income)", conf: "92.1%" },
          { key: "Эмоции", val: "Позитивный настрой (Ad Ready)", conf: "88.4%" },
          { key: "Локация", val: "Парк Горького, Москва", conf: "76.0%" }
        ],
        riskLevel: 'MEDIUM',
        riskTitle: "Таргетинг и Биометрия",
        riskDesc: "ИИ связал твою внешность с брендами одежды. Это позволяет рекламным сетям вычислять твой достаток и предлагать товары с наценкой."
      } as AIReport
    },
    {
      id: 2,
      url: "https://images.unsplash.com/photo-1493612276216-ee3925520721?w=400&h=400&fit=crop",
      title: "Вид из окна",
      report: {
        labels: [
          { key: "Объект", val: "Главное здание МГУ", conf: "100%" },
          { key: "Ракурс", val: "Улица Косыгина, дом 10", conf: "94.5%" },
          { key: "Время", val: "Осень, 16:30 (по теням)", conf: "81.0%" },
          { key: "Приватность", val: "Домашний адрес раскрыт", conf: "99.0%" }
        ],
        riskLevel: 'HIGH',
        riskTitle: "Гео-деанонимизация",
        riskDesc: "Нейросеть мгновенно вычислила твой точный адрес по архитектуре зданий на фоне. Даже без GPS-тэгов ты больше не анонимен."
      } as AIReport
    },
    {
      id: 3,
      url: "https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=400&h=400&fit=crop",
      title: "Друзья",
      report: {
        labels: [
          { key: "Лиц", val: "4 уникальных ID", conf: "100%" },
          { key: "Связи", val: "Общий круг: И. Иванов, А. Петров", conf: "91.2%" },
          { key: "Контекст", val: "Кофейня (Business Meet)", conf: "85.0%" },
          { key: "Устройства", val: "iPhone 15 Pro, Pixel 8", conf: "98.7%" }
        ],
        riskLevel: 'LOW',
        riskTitle: "Социальный Граф",
        riskDesc: "ИИ обновил связи между тобой и твоими знакомыми. Теперь рекламные сети знают, кто на тебя влияет и чьему совету ты доверяешь."
      } as AIReport
    }
  ];

  const startScan = (id: number) => {
    setSelectedPhoto(id);
    setStatus('SCANNING');
    setScanProgress(0);
  };

  useEffect(() => {
    if (status === 'SCANNING') {
      const interval = setInterval(() => {
        setScanProgress(prev => {
          if (prev >= 100) {
            clearInterval(interval);
            setStatus('DONE');
            return 100;
          }
          return prev + 5;
        });
      }, 100);
      return () => clearInterval(interval);
    }
  }, [status]);

  const activePhoto = photos.find(p => p.id === selectedPhoto);

  return (
    <div className="space-y-8 max-w-4xl mx-auto">
      <div className="text-center">
        <h3 className="text-3xl font-black text-[#1e3c72]">Нейро-Анализатор 🤖</h3>
        <p className="text-gray-500 mt-2">Посмотри на мир глазами рекламных нейросетей</p>
      </div>

      <div className="grid grid-cols-3 gap-6">
        {photos.map(p => (
          <button 
            key={p.id}
            onClick={() => status !== 'SCANNING' && startScan(p.id)}
            className={`group relative rounded-[2rem] overflow-hidden border-4 transition-all hover:scale-105 active:scale-95 ${selectedPhoto === p.id ? 'border-blue-500 ring-4 ring-blue-500/20' : 'border-white shadow-xl hover:border-gray-200'}`}
          >
            <img src={p.url} alt={p.title} className={`w-full aspect-square object-cover transition-all ${status === 'SCANNING' && selectedPhoto === p.id ? 'blur-[2px]' : ''}`} />
            <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end justify-center pb-4">
              <span className="text-white font-bold text-sm uppercase tracking-widest">{p.title}</span>
            </div>
            {status === 'SCANNING' && selectedPhoto === p.id && (
                <div className="absolute inset-0 flex items-center justify-center bg-blue-500/20">
                    <div className="text-white font-black text-2xl animate-pulse">{scanProgress}%</div>
                </div>
            )}
          </button>
        ))}
      </div>

      <div className="bg-[#0f111a] rounded-[3rem] p-1 md:p-10 shadow-2xl border-b-8 border-[#1a1c23] relative overflow-hidden min-h-[400px]">
        {/* Tech Background Elements */}
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/10 blur-3xl rounded-full translate-x-10 -translate-y-10"></div>
        <div className="absolute bottom-0 left-0 w-48 h-48 bg-purple-500/5 blur-3xl rounded-full -translate-x-20 translate-y-20"></div>

        {status === 'IDLE' && (
          <div className="flex flex-col items-center justify-center h-full text-center py-20 animate-in fade-in duration-700">
            <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mb-6 border border-white/10">
                <span className="text-4xl">📸</span>
            </div>
            <h4 className="text-white text-xl font-bold mb-2">Ожидание данных...</h4>
            <p className="text-gray-500 max-w-sm">Выберите фотографию выше, чтобы запустить глубокий нейронный анализ метаданных и визуальных векторов.</p>
          </div>
        )}

        {status === 'SCANNING' && (
          <div className="flex flex-col items-center justify-center h-full py-20 relative">
            <div className="text-blue-500 font-mono text-sm mb-8 animate-pulse uppercase tracking-[0.3em]">Neural link established // Scanning...</div>
            <div className="w-full max-w-md h-2 bg-white/5 rounded-full overflow-hidden border border-white/10 mb-4">
                <div className="h-full bg-blue-500 shadow-[0_0_15px_#3b82f6] transition-all duration-300" style={{ width: `${scanProgress}%` }}></div>
            </div>
            <div className="text-white/40 font-mono text-[10px] uppercase">Processing object identification...</div>
            <div className="absolute inset-0 bg-gradient-to-b from-transparent via-blue-500/10 to-transparent h-12 w-full animate-scan-line pointer-events-none"></div>
          </div>
        )}

        {status === 'DONE' && activePhoto && (
          <div className="animate-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col lg:flex-row gap-10">
              <div className="w-full lg:w-1/3 flex flex-col items-center">
                <div className="relative group mb-6">
                    <img src={activePhoto.url} className="w-48 h-48 rounded-[2rem] object-cover border-4 border-white/10 shadow-2xl grayscale hover:grayscale-0 transition-all duration-500" />
