import { GoogleGenAI, Type } from "@google/genai";
import { PhishingTask } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export async function askMentor(question: string) {
  const prompt = `Ты — эксперт по кибербезопасности и цифровой гигиене проекта SafeStep. 
  Твоя задача: ответить на вопрос пользователя "${question}" коротко, профессионально, но понятно для подростка (14-16 лет). 
  Используй современный сленг в меру (например, 'база', 'скам', 'фишинг'). 
  Отвечай на русском языке. Максимум 3 предложения.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error(error);
    return "Ой, мои нейронные связи временно зашифрованы. Попробуй спросить позже!";
  }
}

export async function simulateOsintScan(nickname: string, name: string) {
  const prompt = `Simulate an OSINT search for a person with nickname "${nickname}" and name "${name}". 
  Provide a list of 5-7 fake but realistic sounding "leaked" data points in Russian. 
  Example: "Found on forum game-guru.ru (2018): linked email test@mail.ru", "Geolocation leak from photo on Instagram: near School #5".
  Format: JSON array of strings.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: { type: Type.STRING }
      }
    }
  });

  try {
    return JSON.parse(response.text || "[]");
  } catch {
    return ["Ошибка парсинга данных", "Сканирование прервано"];
  }
}

export async function generatePhishingTask(): Promise<PhishingTask> {
  const prompt = `Generate a realistic phishing email task for a training simulator.
  Include: 
  - sender (name like 'Steam Support' or 'Bank ABC')
  - url (either suspicious like 'steam-security.co' or safe like 'steamcommunity.com')
  - text (the message body in Russian)
  - is_phishing (boolean)
  - hint (why it is or isn't phishing in Russian)
  Return in JSON format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          sender: { type: Type.STRING },
          url: { type: Type.STRING },
          text: { type: Type.STRING },
          is_phishing: { type: Type.BOOLEAN },
          hint: { type: Type.STRING }
        },
        required: ["sender", "url", "text", "is_phishing", "hint"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
}

