import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ARTICLES, BIG_ARTICLES_STORAGE } from '../constants';
import { Layout } from './LayoutWrapper';
import { simulateOsintScan } from '../services/geminiService';
import { generateSecurePassphrase } from '../services/passwordGenerator';
import { IncognitoTool } from '../components/IncognitoTool';
import { SmartphoneSpyTool } from '../components/SmartphoneSpyTool';
import { PhishingTrainer } from '../components/PhishingTrainer';
import { AITool } from '../components/AITool';
import { FinalTool } from '../components/FinalTool';

interface Message {
  id: number;
  sender: string;
  avatar: string;
  text: string;
  isScam: boolean;
  reason: string;
}

const ArticleDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const article = ARTICLES.find(a => a.id === id);
  const [activeTab, setActiveTab] = useState('theory');
  const [zenMode, setZenMode] = useState(false);

  // OSINT State
  const [nick, setNick] = useState('');
  const [terminalLogs, setTerminalLogs] = useState<{ text: string, type: 'sys' | 'warn' | 'crit' }[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Gaming Tool State
  const [gameScore, setGameScore] = useState(0);
  const [currentMessage, setCurrentMessage] = useState<Message | null>(null);
  const [gameFeedback, setGameFeedback] = useState<{ isCorrect: boolean, text: string } | null>(null);

  const gameMessages: Message[] = [
    { id: 1, sender: "SteamSupport_Bot", avatar: "🛡️", text: "Ваш аккаунт будет заблокирован через 2 часа. Срочно перейдите по ссылке steam-security.co для верификации инвентаря.", isScam: true, reason: "Официальная поддержка никогда не пишет в личку. Ссылка 'steam-security.co' — фейк." },
    { id: 2, sender: "BestFriend_007", avatar: "👨‍💻", text: "Бро, проголосуй за мою команду на турнире! Вот линк: esportal-cup.cc. Очень нужно!", isScam: true, reason: "Популярный вид фишинга. Аккаунт друга взломан, ссылка ведет на кражу Steam токена." },
    { id: 3, sender: "Official Discord", avatar: "👾", text: "Вы получили 1 год Nitro бесплатно! Отсканируйте этот QR-код в мобильном приложении для активации.", isScam: true, reason: "Сканирование чужого QR-кода дает хакеру мгновенный доступ к вашему аккаунту." },
    { id: 4, sender: "MarketBot_Trust", avatar: "🤖", text: "Предложение обмена принято. Проверьте детали трейда в официальном приложении Steam.", isScam: false, reason: "Это стандартное уведомление, не требующее перехода по внешним ссылкам." }
  ];

  const spawnGameMessage = () => {
    const randomMsg = gameMessages[Math.floor(Math.random() * gameMessages.length)];
    setCurrentMessage({ ...randomMsg, id: Date.now() });
    setGameFeedback(null);
  };

  const handleGameChoice = (userThinksScam: boolean) => {
    if (!currentMessage) return;
    const isCorrect = userThinksScam === currentMessage.isScam;
    if (isCorrect) setGameScore(s => s + 10);
    setGameFeedback({ isCorrect, text: currentMessage.reason });
    setTimeout(spawnGameMessage, 4000);
  };

  const [geoStep, setGeoStep] = useState<'invite' | 'request' | 'result'>('invite');
  const [isFakeLoading, setIsFakeLoading] = useState(false);

  const handleOsintScan = async () => {
    if (!nick) return alert("Введите никнейм!");
    setIsScanning(true);
    setTerminalLogs([{ text: "Инициализация OSINT-протокола...", type: 'sys' }]);
    const findings = await simulateOsintScan(nick, "");
    setTerminalLogs(findings.map((f: string) => ({ text: f, type: 'warn' })));
    setIsScanning(false);
  };

  if (!article) return <div>Статья не найдена</div>;

  if (zenMode) {
    return (
      <Layout>
        <div className="zen-container px-5 pb-20 animate-in fade-in duration-700 dark:text-gray-100">
          <div dangerouslySetInnerHTML={{ __html: BIG_ARTICLES_STORAGE[article.id] || "Контент в разработке..." }} />
          <div className="text-center mt-12">
            <button onClick={() => setZenMode(false)} className="bg-[#1e3c72] dark:bg-blue-600 text-white px-10 py-4 rounded-2xl font-bold shadow-lg hover:scale-105 transition-transform">
              Закрыть статью и вернуться к практике
            </button>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <main className="container-box article-view">
        <div className="article-header text-center mb-8">
          <span className="text-7xl mb-4 block animate-bounce">{article.emoji}</span>
          <h1 className="text-4xl font-black text-[#1e3c72] dark:text-blue-400 tracking-tight">{article.title}</h1>
          <p className="text-gray-500 dark:text-gray-400 italic mt-2">{article.subtitle}</p>
        </div>

        <div className="tabs flex justify-center gap-2 mb-10 flex-wrap">
          <button className={`tab-btn ${activeTab === 'theory' ? 'active' : ''}`} onClick={() => setActiveTab('theory')}>📖 Информация</button>
          <button className={`tab-btn ${activeTab === 'practice' ? 'active' : ''}`} onClick={() => setActiveTab('practice')}>📜 Правила</button>
          <button className={`tab-btn ${activeTab === 'trainer' ? 'active' : ''}`} onClick={() => setActiveTab('trainer')}>⚙️ Инструмент</button>
        </div>

        {activeTab === 'theory' && (
          <div className="tab-content animate-in slide-in-from-bottom duration-500">
            <h3 className="text-2xl font-bold mb-4 text-[#1e3c72] dark:text-blue-300 uppercase tracking-widest text-sm">О чем эта тема?</h3>
            <p className="text-gray-700 dark:text-gray-100 leading-relaxed text-lg mb-8">{article.description}</p>
            <div className="alert-box dark:bg-blue-900/10 dark:border-blue-500">
              <b className="text-yellow-600 dark:text-yellow-400">SafeStep Tip:</b> Понимание рисков — это 50% защиты. Остальное — правильные инструменты.
            </div>
            {BIG_ARTICLES_STORAGE[article.id] && (
              <div className="mt-12 p-10 bg-gradient-to-br from-[#1e3c72] to-[#2a5298] dark:from-blue-900 dark:to-slate-900 rounded-3xl text-white text-center shadow-xl border border-white/10">
                <h4 className="text-2xl font-bold mb-3">Готов к глубокому погружению?</h4>
                <p className="opacity-80 mb-8">Мы подготовили исчерпывающий материал на 300+ слов с реальными кейсами и секретами безопасности.</p>
                <button onClick={() => setZenMode(true)} className="bg-white text-[#1e3c72] dark:bg-blue-500 dark:text-white px-12 py-4 rounded-2xl font-black hover:scale-105 transition-transform shadow-lg">
                  Читать полный лонгрид 📖
                </button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'practice' && (
          <div className="tab-content animate-in slide-in-from-bottom duration-500">
            <h3 className="text-2xl font-bold mb-6 text-[#1e3c72] dark:text-blue-300">Золотые правила ✅</h3>
            <div className="grid gap-4">
              <div className="case-item flex items-center gap-4 dark:bg-slate-900/40">
                <div className="w-10 h-10 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full flex items-center justify-center font-bold shrink-0">1</div>
                <p className="font-medium text-gray-700 dark:text-gray-200">Никогда не переходи по ссылкам из личных сообщений, даже если их прислал "админ".</p>
              </div>
              <div className="case-item flex items-center gap-4 dark:bg-slate-900/40">
                <div className="w-10 h-10 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full flex items-center justify-center font-bold shrink-0">2</div>
                <p className="font-medium text-gray-700 dark:text-gray-200">Включай 2FA (двухфакторку) везде. Твой аккаунт — твоя крепость.</p>
              </div>
              <div className="case-item flex items-center gap-4 dark:bg-slate-900/40">
                <div className="w-10 h-10 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full flex items-center justify-center font-bold shrink-0">3</div>
                <p className="font-medium text-gray-700 dark:text-gray-200">Проверяй домены: g0ogle — это не google. gosuslugi-pay — это не gosuslugi.</p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'trainer' && (
          <div className="tab-content animate-in fade-in duration-500">
            {article.id === 'gaming' && (
              <div className="space-y-6">
                <div className="text-center">
                  <h3 className="text-2xl font-black text-[#1e3c72] dark:text-blue-400">Trade Guardian 🛡️</h3>
                  <p className="text-gray-500 dark:text-gray-400 mb-2">Распознай фишинг в личных сообщениях. Счет: <b>{gameScore}</b></p>
                </div>
                {/* ... rest of gaming tool code ... */}
                {!currentMessage ? (
                  <div className="bg-gray-100 dark:bg-slate-900 p-12 rounded-[40px] text-center border-4 border-dashed border-[#1e3c72]/20">
                    <button onClick={spawnGameMessage} className="read-more-btn max-w-xs mx-auto text-xl">Начать симуляцию 🚀</button>
                  </div>
                ) : (
                  <div className="bg-[#1a1c23] p-8 rounded-[40px] shadow-2xl relative overflow-hidden border border-white/5">
                    <div className="flex items-start gap-4 mb-6">
                      <div className="w-12 h-12 bg-blue-500/20 text-2xl flex items-center justify-center rounded-2xl shrink-0">{currentMessage.avatar}</div>
                      <div className="flex-grow">
                        <div className="text-white font-bold text-sm mb-1">{currentMessage.sender} <span className="text-[10px] text-blue-400 opacity-60 ml-2 uppercase">Online</span></div>
                        <div className="bg-[#2a2e38] text-gray-200 p-4 rounded-2xl rounded-tl-none border border-gray-700 shadow-inner">{currentMessage.text}</div>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 mt-8">
                      <button onClick={() => handleGameChoice(false)} className="py-4 rounded-2xl bg-green-600/20 text-green-400 border-2 border-green-600/50 font-black hover:bg-green-600 hover:text-white transition-all" disabled={!!gameFeedback}>Всё чисто ✅</button>
                      <button onClick={() => handleGameChoice(true)} className="py-4 rounded-2xl bg-red-600/20 text-red-400 border-2 border-red-600/50 font-black hover:bg-red-600 hover:text-white transition-all" disabled={!!gameFeedback}>Это СКАМ! 🏴‍☠️</button>
                    </div>
                    {gameFeedback && (
                      <div className={`mt-6 p-6 rounded-3xl animate-in slide-in-from-bottom duration-300 border-2 ${gameFeedback.isCorrect ? 'bg-green-600/10 border-green-600 text-green-400' : 'bg-red-600/10 border-red-500 text-red-400'}`}>
                        <div className="font-black mb-1">{gameFeedback.isCorrect ? 'ВЕРНО! 🎯' : 'ОШИБКА! 💥'}</div>
                        <div className="text-sm opacity-90">{gameFeedback.text}</div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
            {article.id === 'incognito' && <IncognitoTool />}
            {article.id === 'smartphone_spy' && <SmartphoneSpyTool />}
            {article.id === 'phishing' && <PhishingTrainer />}
            {article.id === 'aiandyourphotos' && <AITool />}
            {article.id === 'final_summary' && <FinalTool />}
            {article.id === 'past_revision' && (
              <div className="space-y-6">
                <input className="w-full p-5 bg-white dark:bg-slate-900 text-[#1e3c72] dark:text-blue-400 border-2 border-[#1e3c72]/20 rounded-xl font-black text-xl placeholder-gray-400" placeholder="Введи ник (напр. IWOSS)" value={nick} onChange={e => setNick(e.target.value)} />
                <button onClick={handleOsintScan} disabled={isScanning} className="read-more-btn py-5 text-xl">{isScanning ? 'ИДЕТ ПОИСК...' : 'Аудит личности 🕵️'}</button>
                <div id="terminal" className="mt-6">
                  {terminalLogs.length === 0 && <div className="opacity-40 italic">Ожидание протокола...</div>}
                  {terminalLogs.map((l, i) => <div key={i} className="mb-2 font-mono"><span className="opacity-50 mr-2">></span>{l.text}</div>)}
                </div>
              </div>
            )}
            {article.id === 'passwords' && (
              <div className="space-y-8 text-center">
                <h3 className="text-2xl font-black text-[#1e3c72] dark:text-blue-400">Генератор "Сейф" 🔐</h3>
                <div className="bg-white dark:bg-slate-900 border-4 border-gray-100 dark:border-slate-800 rounded-[40px] p-12 shadow-2xl relative">
                  <div className="text-2xl md:text-3xl font-mono font-black text-[#1e3c72] dark:text-white mb-10 select-all bg-gray-50 dark:bg-black/40 p-8 rounded-3xl border-2 border-dashed border-blue-500/20">{nick || '••••_••••_••••'}</div>
                  <button onClick={() => setNick(generateSecurePassphrase())} className="read-more-btn py-6 text-2xl">Сгенерировать ⚡</button>
                </div>
              </div>
            )}
          </div>
        )}

        <div className="mt-12 text-center border-t border-gray-100 dark:border-slate-800 pt-8">
          <Link to="/articles" className="text-gray-400 hover:text-[#1e3c72] dark:hover:text-blue-400 font-black transition-colors uppercase tracking-widest text-sm">
            ← Назад к списку тем
          </Link>
        </div>
      </main>
    </Layout>
  );
};

export default ArticleDetail;

import React, { useState, useEffect } from 'react';
import { QUIZ_DATA } from '../constants';
import { Layout } from './LayoutWrapper';

const Quiz: React.FC = () => {
  const [currentStep, setCurrentStep] = useState(0);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);
  const [feedback, setFeedback] = useState<{ isCorrect: boolean, text: string } | null>(null);
  const [rank, setRank] = useState('');
  const [userName, setUserName] = useState('');

  const progress = ((currentStep + 1) / QUIZ_DATA.length) * 100;

  useEffect(() => {
    if (finished) {
        if (score === QUIZ_DATA.length) setRank('ПРИЗРАК СЕТИ 👻');
        else if (score > 15) setRank('МАСТЕР КРЕПОСТИ 🏰');
        else if (score > 10) setRank('ОПЫТНЫЙ ПОЛЬЗОВАТЕЛЬ 🛡️');
        else setRank('ЦИФРОВОЙ НОВИЧОК 👶');
    }
  }, [finished, score]);

  const handleAnswer = (idx: number) => {
    const question = QUIZ_DATA[currentStep];
    const isCorrect = idx === question.correct;

    if (isCorrect) setScore(s => s + 1);
    setFeedback({ isCorrect, text: isCorrect ? question.desc : "Ловушка сработала! На самом деле: " + question.desc });

    setTimeout(() => {
        setFeedback(null);
        if (currentStep < QUIZ_DATA.length - 1) {
            setCurrentStep(s => s + 1);
        } else {
            setFinished(true);
        }
    }, 3000);
  };

  return (
    <Layout>
      <header className="hero-gradient pt-16 pb-24 md:pt-20 md:pb-32 px-5 text-center">
        <h1 className="text-4xl md:text-5xl font-black mb-4">Cyber IQ Test</h1>
        <p className="text-lg md:text-xl opacity-90 max-w-xl mx-auto">20 вопросов с подвохами, чтобы проверить твою реальную защиту</p>
      </header>

      <main className="container-box mt-[-60px] md:mt-[-80px] p-6 md:p-10">
        <div className="w-full">
            {!finished && (
              <div className="mb-8">
                <div className="flex justify-between items-end mb-2">
                    <span className="text-xs font-black uppercase tracking-widest text-[#1e3c72] dark:text-blue-400">Прогресс защиты</span>
                    <span className="text-sm font-mono font-bold">{currentStep + 1} / {QUIZ_DATA.length}</span>
                </div>
                <div className="w-full bg-gray-100 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-[#1e3c72] dark:bg-blue-500 transition-all duration-500 shadow-[0_0_10px_rgba(30,60,114,0.3)]" 
                      style={{ width: `${progress}%` }}
                    ></div>
                </div>
              </div>
            )}

            {finished ? (
                <div className="text-center py-6 md:py-10 animate-in zoom-in duration-500">
                    {!userName ? (
                      <div className="max-w-md mx-auto space-y-6">
                        <h3 className="text-2xl font-black text-[#1e3c72] dark:text-white uppercase">Твой результат готов!</h3>
                        <p className="text-gray-500 dark:text-gray-400">Введи свое имя, чтобы получить сертификат:</p>
                        <input 
                          className="w-full p-4 rounded-xl border-2 dark:bg-slate-800 dark:border-slate-700 outline-none focus:border-blue-500 text-center text-xl font-bold dark:text-white"
                          placeholder="Имя Фамилия"
                          value={userName}
                          onChange={(e) => { if(e.target.value.length < 25) setUserName(e.target.value); }}
                        />
                        <button onClick={() => setUserName(userName || 'Аноним')} className="read-more-btn">Создать сертификат 💳</button>
                      </div>
                    ) : (
                      <div className="certificate-card mx-auto max-w-2xl mb-12">
                        <div className="flex justify-between items-start mb-10">
                          <div className="text-left">
                            <h2 className="text-3xl font-black uppercase tracking-tighter">SAFESTEP PASS</h2>
                            <p className="text-[10px] font-mono opacity-60">SERIAL: {Math.random().toString(36).substr(2, 9).toUpperCase()}</p>
                          </div>
                          <div className="text-4xl">🛡️</div>
                        </div>

                        <div className="space-y-4 text-left">
                          <div>
                            <p className="text-[10px] uppercase font-bold opacity-40 mb-1">Holder Name</p>
                            <p className="text-2xl font-black tracking-widest uppercase">{userName}</p>
                          </div>
                          <div className="grid grid-cols-2 gap-4">
                            <div>
                              <p className="text-[10px] uppercase font-bold opacity-40 mb-1">Clearance Level</p>
                              <p className="font-black text-blue-600 dark:text-blue-400">{rank}</p>
                            </div>
                            <div>
                              <p className="text-[10px] uppercase font-bold opacity-40 mb-1">Score</p>
                              <p className="font-black">{score} / {QUIZ_DATA.length}</p>
                            </div>
                          </div>
                        </div>

                        <div className="mt-10 pt-6 border-t border-blue-500/20 text-center">
                          <p className="text-[10px] font-mono opacity-50 uppercase tracking-widest">Digital Hygiene Certified • 2026 • Verified System</p>
                        </div>
                      </div>
                    )}

                    {userName && (
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-lg mx-auto">
                        <button onClick={() => window.location.reload()} className="read-more-btn bg-[#1e3c72] dark:bg-blue-600">Повторить ↻</button>
                        <a href="#/articles" className="read-more-btn bg-gray-100 dark:bg-slate-700 !text-gray-700 dark:!text-white border border-gray-200 dark:border-slate-600">В базу знаний</a>
                      </div>
                    )}
                </div>
            ) : (
                <div className="question-block animate-in fade-in duration-500">
                    <p className="text-xl md:text-2xl font-black mb-8 text-[#1e3c72] dark:text-white leading-tight min-h-[60px]">
                      {QUIZ_DATA[currentStep].q}
                    </p>
                    {/* ... answers loop ... */}
                    <div className="grid grid-cols-1 gap-4">
                        {QUIZ_DATA[currentStep].options.map((opt, i) => (
                            <button 
                                key={i} 
                                onClick={() => !feedback && handleAnswer(i)}
                                className={`w-full p-5 md:p-6 text-left border-2 rounded-2xl font-bold transition-all flex items-center gap-4 group ${
                                  feedback 
                                    ? 'cursor-not-allowed opacity-50' 
                                    : 'border-gray-100 dark:border-slate-700 bg-gray-50 dark:bg-slate-900/50 hover:border-[#1e3c72] dark:hover:border-blue-500 hover:translate-x-2'
                                }`}
                                disabled={!!feedback}
                            >
                                <span className="w-8 h-8 rounded-full bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-600 flex items-center justify-center shrink-0 text-xs group-hover:bg-[#1e3c72] dark:group-hover:bg-blue-500 group-hover:text-white transition-colors">
                                  {String.fromCharCode(65 + i)}
                                </span>
                                <span className="text-gray-700 dark:text-gray-200 group-hover:text-[#1e3c72] dark:group-hover:text-blue-300">{opt}</span>
                            </button>
                        ))}
                    </div>

                    {feedback && (
                        <div className={`mt-8 p-6 rounded-2xl font-bold animate-in slide-in-from-bottom duration-300 border-l-8 ${
                          feedback.isCorrect 
                            ? 'bg-green-50 dark:bg-green-900/20 border-green-500 text-green-800 dark:text-green-300' 
                            : 'bg-red-50 dark:bg-red-900/20 border-red-500 text-red-800 dark:text-red-300'
                        }`}>
                            <div className="flex items-center gap-2 mb-2 text-lg">
                              <span>{feedback.isCorrect ? '🎯' : '⚠️'}</span>
                              <span>{feedback.isCorrect ? 'ТОЧНО В ЦЕЛЬ!' : 'ПОПАЛСЯ!'}</span>
                            </div>
                            <div className="text-sm md:text-base opacity-90 leading-relaxed">{feedback.text}</div>
                        </div>
                    )}
                </div>
            )}
        </div>
      </main>
    </Layout>
  );
};

export default Quiz;

import { GoogleGenAI, Type } from "@google/genai";
import { PhishingTask } from "../types";

// Using gemini-flash-latest as it is the most stable alias for free tier projects
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
const STABLE_MODEL = 'gemini-flash-latest';

export async function askMentor(question: string) {
  const prompt = `Ты — эксперт по кибербезопасности и цифровой гигиене проекта SafeStep. 
  Твоя задача: ответить на вопрос пользователя "${question}" коротко, профессионально, но понятно для подростка (14-16 лет). 
  Используй современный сленг в меру (например, 'база', 'скам', 'фишинг'). 
  Отвечай на русском языке. Максимум 3 предложения.`;

  try {
    const response = await ai.models.generateContent({
      model: STABLE_MODEL,
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Мои нейронные фильтры временно перегружены. Попробуй задать вопрос чуть позже, а пока изучи статьи!";
  }
}

export async function simulateOsintScan(nickname: string, name: string) {
  const prompt = `Simulate an OSINT search for a person with nickname "${nickname}" and name "${name}". 
  Provide a list of 5-7 fake but realistic sounding "leaked" data points in Russian. 
  Example: "Found on forum game-guru.ru (2018): linked email test@mail.ru", "Geolocation leak from photo on Instagram: near School #5".
  Format: JSON array of strings.`;

  try {
    const response = await ai.models.generateContent({
      model: STABLE_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("OSINT Error:", error);
    return ["Система OSINT временно недоступна", "Проверьте подключение к сети"];
  }
}

export async function generatePhishingTask(): Promise<PhishingTask> {
  const prompt = `Generate a realistic phishing email task for a training simulator.
  Include: 
  - sender (name like 'Steam Support' or 'Bank ABC')
  - url (either suspicious like 'steam-security.co' or safe like 'steamcommunity.com')
  - text (the message body in Russian)
  - is_phishing (boolean)
  - hint (why it is or isn't phishing in Russian)
  Return in JSON format.`;

  try {
    const response = await ai.models.generateContent({
      model: STABLE_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            sender: { type: Type.STRING },
            url: { type: Type.STRING },
            text: { type: Type.STRING },
            is_phishing: { type: Type.BOOLEAN },
            hint: { type: Type.STRING }
          },
          required: ["sender", "url", "text", "is_phishing", "hint"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Phishing Gen Error:", error);
    throw error;
  }
}

