import { GoogleGenAI, Type } from "@google/genai";
import { PhishingTask } from "../types";

// Using gemini-flash-lite-latest which is highly available on free tier
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
const MODEL_NAME = 'gemini-flash-lite-latest';

export async function askMentor(question: string) {
  const prompt = `Ты — эксперт по кибербезопасности проекта SafeStep. 
  Ответь на вопрос пользователя "${question}" коротко (макс 3 предложения), профессионально, но понятно для подростка. 
  Используй русский язык.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("AI Error:", error);
    return "Мои нейронные фильтры временно перегружены. Попробуй задать вопрос чуть позже!";
  }
}

export async function simulateOsintScan(nickname: string, name: string) {
  const prompt = `Simulate an OSINT search for a person with nickname "${nickname}". 
  Provide 5-7 fake but realistic findings in Russian. 
  Format as JSON array of strings.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    return ["Результаты зашифрованы", "Попробуйте позже"];
  }
}

export async function generatePhishingTask(): Promise<PhishingTask> {
  const prompt = `Generate a realistic phishing email task in Russian.
  Include sender, url, text, is_phishing (bool), hint. Return JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            sender: { type: Type.STRING },
            url: { type: Type.STRING },
            text: { type: Type.STRING },
            is_phishing: { type: Type.BOOLEAN },
            hint: { type: Type.STRING }
          },
          required: ["sender", "url", "text", "is_phishing", "hint"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw error;
  }
}

