  const [rank, setRank] = useState('');
  const [userName, setUserName] = useState('');

  const progress = ((currentStep + 1) / QUIZ_DATA.length) * 100;

  useEffect(() => {
    if (finished) {
        if (score === QUIZ_DATA.length) setRank('ПРИЗРАК СЕТИ 👻');
        else if (score > 15) setRank('МАСТЕР КРЕПОСТИ 🏰');
