const ThreatMap: React.FC = () => {
    const [attacks, setAttacks] = useState<{id: number, top: number, left: number}[]>([]);

    useEffect(() => {
        const interval = setInterval(() => {
            const newAttack = {
                id: Date.now(),
                top: Math.random() * 80 + 10,
                left: Math.random() * 80 + 10
