                <div 
                    key={attack.id} 
                    className="threat-map-dot absolute w-2 h-2 bg-red-500 rounded-full animate-pulse shadow-[0_0_10px_red]" 
                    style={{ top: `${attack.top}%`, left: `${attack.left}%` }}
