                    <div className="text-blue-500 font-black text-[10px] uppercase tracking-widest mb-4">Ближайшая цель</div>
                    <h4 className="text-xl font-black mb-4 dark:text-white leading-tight min-h-[3rem]">{score === 100 ? 'Ты прошел всё!' : `Модуль: ${nextModuleTitle}`}</h4>
                    <Link to={score === 100 ? "/articles" : `/article/${nextModuleId}`} className="inline-flex items-center gap-2 text-blue-600 font-bold text-sm hover:underline group">
                        {score === 100 ? 'Повторить базу' : 'Приступить к анализу'}
