                  {num === 3 && "Проверяй написание домена в адресной строке: g0ogle.com - это обман."}
                </p>
              </div>
            ))}
            <div className="text-center mt-10">
                <button onClick={markComplete} className="text-[10px] font-black text-blue-500 uppercase tracking-widest hover:opacity-70 transition-opacity">Отметить как изученное ✅</button>
            </div>
          </div>
        )}

        {activeTab === 'trainer' && (
          <div className="animate-in fade-in duration-500 min-h-[350px]">
            {article.id === 'incognito' && <IncognitoTool onComplete={markComplete} />}
            {/* Added onComplete prop to track completion */}
            {article.id === 'smartphone_spy' && <SmartphoneSpyTool onComplete={markComplete} />}
            {/* Added onComplete prop to track completion */}
            {article.id === 'phishing' && <PhishingTrainer onComplete={markComplete} />}
            {article.id === 'gaming' && <GamingTool onComplete={markComplete} />}
            {article.id === 'geolocation' && <GeolocationTool onComplete={markComplete} />}
            {article.id === 'aiandyourphotos' && <AITool onComplete={markComplete} />}
            {article.id === 'final_summary' && <FinalTool onComplete={markComplete} />}
            {article.id === 'past_revision' && (
              <div className="space-y-8">
                <div className="relative group">
                    <input className="w-full p-6 md:p-8 bg-slate-50 dark:bg-slate-900 text-blue-600 dark:text-blue-400 border-2 border-transparent focus:border-blue-500 rounded-[2rem] font-black text-xl md:text-2xl placeholder-slate-400 outline-none transition-all shadow-inner" placeholder="Введи ник для анализа..." value={nick} onChange={e => setNick(e.target.value)} />
                    <div className="absolute right-6 top-1/2 -translate-y-1/2 opacity-20 text-3xl">🔍</div>
                </div>
                <button onClick={handleOsintScan} disabled={isScanning} className="w-full bg-blue-600 hover:bg-blue-500 text-white py-6 md:py-8 rounded-[2rem] font-black text-xl md:text-2xl shadow-2xl hover:scale-[1.01] active:scale-95 transition-all disabled:opacity-50">
                   {isScanning ? 'АНАЛИЗИРУЮ ДАННЫЕ...' : 'Запустить ИИ-аудит 🕵️'}
                </button>
                <div id="terminal" className="mt-10 bg-slate-950 p-6 md:p-10 rounded-[2rem] font-mono text-xs md:text-sm text-blue-400 border border-slate-800 shadow-2xl overflow-hidden relative min-h-[200px]">
                  <div className="scanline-overlay animate-scanline"></div>
                  {terminalLogs.length === 0 ? <div className="opacity-30 italic animate-pulse">> Ожидание вводных данных...</div> : terminalLogs.map((l, i) => <div key={i} className="mb-2 flex gap-4"><span className="opacity-30">[{new Date().toLocaleTimeString()}]</span><span className="text-white font-bold">{l.text}</span></div>)}
                </div>
              </div>
            )}
            {article.id === 'passwords' && (
              <div className="text-center py-6 md:py-12">
                <div className="text-6xl md:text-7xl mb-8">🔐</div>
                <h3 className="text-2xl md:text-3xl font-black mb-8 text-slate-800 dark:text-white">Генератор "Сейф-Фраз"</h3>
                <div className="bg-slate-50 dark:bg-slate-900 border-4 border-dashed border-blue-500/10 rounded-[2.5rem] p-8 md:p-16 mb-10 shadow-inner">
                   <div className="text-2xl md:text-4xl font-mono font-black text-blue-600 dark:text-white mb-8 md:text-12 tracking-tighter break-all">{nick || '••••_••••_••••'}</div>
                   <button onClick={() => { setNick(generateSecurePassphrase()); markComplete(); }} className="bg-blue-600 hover:bg-blue-700 text-white px-10 md:px-16 py-4 rounded-xl font-black hover:scale-105 active:scale-95 transition-all shadow-xl uppercase tracking-widest text-xs">Сгенерировать фразу ⚡</button>
                </div>
              </div>
            )}
          </div>
        )}

        <div className="mt-24 text-center border-t border-gray-100 dark:border-slate-800 pt-12">
          <Link to="/articles" className="text-slate-400 hover:text-blue-500 font-black transition-colors uppercase tracking-[0.3em] text-[10px]">
            ← Вернуться к библиотеке SafeStep
          </Link>
        </div>
      </main>
    </Layout>
  );
};

